  `owner` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建者用户名',
  `download_count` bigint NOT NULL DEFAULT '0' COMMENT '下载次数',
  PRIMARY KEY (`id`),
