--
-- Table structure for table `his_config_info`
--

DROP TABLE IF EXISTS `his_config_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `his_config_info` (
  `id` bigint unsigned NOT NULL COMMENT 'id',
  `nid` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT 'nid, 自增标识',
  `data_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'data_id',
  `group_id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'group_id',
  `app_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'app_name',
  `content` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'content',
  `md5` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'md5',
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `src_user` text COLLATE utf8mb4_unicode_ci COMMENT 'source user',
  `src_ip` varchar(50) CHARACTER SET utf8 COLLATE utf8_bin DEFAULT NULL,
  `op_type` char(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'operation type',
  `tenant_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '租户字段',
  `encrypted_data_key` varchar(1024) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '密钥',
  `publish_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'formal' COMMENT 'publish type gray or formal',
  `gray_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'gray name',
  `ext_info` longtext COLLATE utf8mb4_unicode_ci COMMENT 'ext info',
  PRIMARY KEY (`nid`),
  KEY `idx_gmt_create` (`gmt_create`),
  KEY `idx_gmt_modified` (`gmt_modified`),
  KEY `idx_did` (`data_id`)
) ENGINE=InnoDB AUTO_INCREMENT=84 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='多租户改造';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `his_config_info`
--

LOCK TABLES `his_config_info` WRITE;
/*!40000 ALTER TABLE `his_config_info` DISABLE KEYS */;
INSERT INTO `his_config_info` VALUES (2,71,'blade.yaml','DEFAULT_GROUP','','#服务器配置\nserver:\n  undertow:\n    # 以下的配置会影响buffer,这些buffer会用于服务器连接的IO操作,有点类似netty的池化内存管理\n    buffer-size: 1024\n    # 是否分配的直接内存\n    direct-buffers: true\n    # 线程配置\n    threads:\n      # 设置IO线程数, 它主要执行非阻塞的任务,它们会负责多个连接, 默认设置每个CPU核心一个线程\n      io: 16\n      # 阻塞任务线程池, 当执行类似servlet请求阻塞操作, undertow会从这个线程池中取得线程,它的值设置取决于系统的负载\n      worker: 400\n\n#spring配置\nspring:\n  cloud:\n    sentinel:\n      eager: true\n  gateway:\n    routes:\n      - id: blade-mall\n        uri: lb://blade-mall\n        predicates:\n          - Path=/blade-mall/**\n        filters:\n          - StripPrefix=1\n  devtools:\n    restart:\n      log-condition-evaluation-delta: false\n    livereload:\n      port: 23333\n\n#feign配置\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n\n#对外暴露端口\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \"*\"\n  endpoint:\n    health:\n      show-details: always\n\n#springdoc-openapi配置\nspringdoc:\n  default-flat-param-object: true\n\n#knife4j配置\nknife4j:\n  #启用\n  enable: true\n  #基础认证\n  basic:\n    enable: false\n    username: blade\n    password: blade\n  #增强配置\n  setting:\n    enableSwaggerModels: true\n    enableDocumentManage: true\n    enableHost: false\n    enableHostText: http://localhost\n    enableRequestCache: true\n    enableFilterMultipartApis: false\n    enableFilterMultipartApiMethodType: POST\n    language: zh_cn\n    enableFooter: false\n    enableFooterCustom: true\n    footerCustomContent: Copyright © 2026 SpringBlade All Rights Reserved\n\n#swagger配置信息\nswagger:\n  title: SpringBlade 接口文档系统\n  description: SpringBlade 接口文档系统\n  version: 4.8.0\n  license: Powered By SpringBlade\n  licenseUrl: https://bladex.cn\n  terms-of-service-url: https://bladex.cn\n  contact:\n    name: smallchill\n    email: bladejava@qq.com\n    url: https://gitee.com/smallc\n\n#blade配置\nblade:\n  datasource:\n    dev:\n      url: jdbc:mysql://localhost:3306/blade?useSSL=false&serverTimezone=Asia/Shanghai&characterEncoding=utf8mb4\n      username: root\n      password: 123456\n    order:\n      url: jdbc:mysql://localhost:3306/blade_order?useSSL=false&serverTimezone=Asia/Shanghai&characterEncoding=utf8mb4\n      username: root\n      password: 123456\n    pay:\n      url: jdbc:mysql://localhost:3306/blade_pay?useSSL=false&serverTimezone=Asia/Shanghai&characterEncoding=utf8mb4\n      username: root\n      password: 123456\n    workflow:\n      url: jdbc:mysql://localhost:3306/blade_workflow?useSSL=false&serverTimezone=Asia/Shanghai&characterEncoding=utf8mb4\n      username: root\n      password: 123456\n  upload-path: d:\\workproject\\springbladeandreact\\springBlade\\uploads\n\n  # =============================================\n  # 文件上传统一配置（所有服务共用）\n  # =============================================\n  file:\n    # 是否启用增强功能（加密、压缩、数据库存储）\n    enabled: true\n    # 统一上传目录\n    upload-dir: upload\n    # 是否ZIP压缩（true=所有上传的文件都会压缩成zip格式）\n    zip-enabled: true\n    # 是否AES加密（true=所有上传的文件都会AES加密）\n    encrypt-enabled: false\n    # 是否保存到ImageFile数据库表（true=所有文件元数据存入ImageFile表）\n    save-to-db: true\n    # 图片尺寸压缩（仅对图片生效，减小图片分辨率/质量）\n    image-compress: true\n\n  auth:\n    #使用 @org.springblade.test.Sm2KeyGenerator 获取,用于国密sm2验签,需和前端保持一致\n    public-key: 04ac02fe94f4cac62a57a2335cc96a075a1ee41cea3b211bd7acbb9cf579b7e601b9ece2b0cfab64dca268b6942bf556af67cfe226a5cf28d936039c43e4bb12c1\n    #使用 @org.springblade.test.Sm2KeyGenerator 获取,用于国密sm2解密,前端无需配置\n    private-key: 00ac7fde22ecf5a764ea69b7ca8205383d98e7459e765bc1bd092f62c5f85267f9\n  token:\n    #使用 @org.springblade.test.SignKeyGenerator 获取\n    sign-key: qHJlcyzQ7YoGmHA7wZzvioTKYzYMaugG\n    #使用 @org.springblade.test.SignKeyGenerator 获取\n    aes-key: hJtodEd1qzJX9UOB9RBFdWk9KrAb59fH\n  xss:\n    enabled: true\n    skip-url:\n      - /weixin\n  secure:\n    skip-url:\n      - /test/**\n      - /blade-mall/front/**\n      - /blade-mall/uploads/**\n      - /blade-mall/file/download/**\n      - /blade-mall/auth/**\n      - /blade-mall/upload/**\n      - /file/download/**\n      - /front/**\n      - /uploads/**\n      - /auth/**\n    client:\n      - client-id: sword\n        path-patterns:\n          - /sword/**\n      - client-id: saber\n        path-patterns:\n          - /saber/**\n      - client-id: sword\n        path-patterns:\n          - /blade-mall/front/**\n  tenant:\n    column: tenant_id\n    tables:\n      - blade_notice\n\n# 微信小程序配置\nwechat:\n  miniapp:\n    appid: wx3d4a76c14ed1683b  # 请替换为实际的小程序AppID\n    secret: b1f771b0d92b9dcca5b260d91de53c22  # 请替换为实际的小程序AppSecret\n\n  # 微信支付配置\n  pay:\n    enabled: false  # 是否启用微信支付（true: 启用，false: 禁用）\n    appid: wx3d4a76c14ed1683b  # 小程序 AppID\n    mch-id: 1900000000  # 商户号，请替换为实际的商户号\n    mch-serial-no: b1f771b0d92b9dcca5b260d91de53c22  # 商户证书序列号\n    api-v3-key: your_api_v3_key_here  # APIv3 密钥（32 位）\n    private-key-path: src/main/resources/certs/apiclient_key.pem  # 商户私钥路径（需从微信商户平台下载）\n    platform-cert-path: src/main/resources/certs/wechatpay_cert.pem  # 微信支付平台证书路径\n    notify-url: https://your-domain.com/api/pay/wechat/notify  # 支付结果通知地址\n    refund-notify-url: https://your-domain.com/api/pay/wechat/refund/notify  # 退款通知地址\n\n# 第三方平台配置\nthird-party:\n  # 微信公众号/开放平台配置\n  wechat:\n    app-id: wxc771b90f4d13039e  # 请替换为实际的微信AppID\n    app-secret: 20be435da6771c5d86c4fd6eb097ad9b  # 请替换为实际的微信AppSecret\n    access-token-url: https://api.weixin.qq.com/sns/oauth2/access_token\n    user-info-url: https://api.weixin.qq.com/sns/userinfo\n  # 抖音配置\n  douyin:\n    client-key: your_douyin_client_key  # 请替换为实际的抖音Client Key\n    client-secret: your_douyin_client_secret  # 请替换为实际的抖音Client Secret\n    access-token-url: https://open.douyin.com/oauth/access_token/\n    user-info-url: https://open.douyin.com/oauth/userinfo/','517dba808b4219d75a3b2d9488a32022','2026-09-20 22:37:33','2026-09-20 14:37:34','nacos','192.168.1.5','U','public','','formal','','{\"type\"