yaml','DEFAULT_GROUP','','#服务器配置\nserver:\n  undertow:\n    # 以下的配置会影响buffer,这些buffer会用于服务器连接的IO操作,有点类似netty的池化内存管理\n    buffer-size: 1024\n    # 是否分配的直接内存\n    direct-buffers: true\n    # 线程配置\n    threads:\n      # 设置IO线程数, 它主要执行非阻塞的任务,它们会负责多个连接, 默认设置每个CPU核心一个线程\n      io: 16\n      # 阻塞任务线程池, 当执行类似servlet请求阻塞操作, undertow会从这个线程池中取得线程,它的值设置取决于系统的负载\n      worker: 400\n\n#spring配置\nspring:\n  cloud:\n    sentinel:\n      eager: true\n  gateway:\n    routes:\n      - id: blade-mall\n        uri: lb://blade-mall\n        predicates:\n          - Path=/blade-mall/**\n        filters:\n          - StripPrefix=1\n  devtools:\n    restart:\n      log-condition-evaluation-delta: false\n    livereload:\n      port: 23333\n\n#feign配置\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n\n#对外暴露端口\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \"*\"\n  endpoint:\n    health:\n      show-details: always\n\n#springdoc-openapi配置\nspringdoc:\n  default-flat-param-object: true\n\n#knife4j配置\nknife4j:\n  #启用\n  enable: true\n  #基础认证\n  basic:\n    enable: false\n    username: blade\n    password: blade\n  #增强配置\n  setting:\n    enableSwaggerModels: true\n    enableDocumentManage: true\n    enableHost: false\n    enableHostText: http://localhost\n    enableRequestCache: true\n    enableFilterMultipartApis: false\n    enableFilterMultipartApiMethodType: POST\n    language: zh_cn\n    enableFooter: false\n    enableFooterCustom: true\n    footerCustomContent: Copyright © 2026 SpringBlade All Rights Reserved\n\n#swagger配置信息\nswagger:\n  title: SpringBlade 接口文档系统\n  description: SpringBlade 接口文档系统\n  version: 4.8.0\n  license: Powered By SpringBlade\n  licenseUrl: https://bladex.cn\n  terms-of-service-url: https://bladex.cn\n  contact:\n    name: smallchill\n    email: bladejava@qq.com\n    url: https://gitee.com/smallc\n\n#blade配置\nblade:\n  datasource:\n    dev:\n      url: jdbc:mysql://localhost:3306/blade?useSSL=false&serverTimezone=Asia/Shanghai&characterEncoding=utf8mb4\n      username: root\n      password: 123456\n    order:\n      url: jdbc:mysql://localhost:3306/blade_order?useSSL=false&serverTimezone=Asia/Shanghai&characterEncoding=utf8mb4\n      username: root\n      password: 123456\n    pay:\n      url: jdbc:mysql://localhost:3306/blade_pay?useSSL=false&serverTimezone=Asia/Shanghai&characterEncoding=utf8mb4\n      username: root\n      password: 123456\n    workflow:\n      url: jdbc:mysql://localhost:3306/blade_workflow?useSSL=false&serverTimezone=Asia/Shanghai&characterEncoding=utf8mb4\n      username: root\n      password: 123456\n  upload-path: d:\\workproject\\springbladeandreact\\springBlade\\uploads\n\n  # =============================================\n  # 文件上传统一配置（所有服务共用）\n  # =============================================\n  file:\n    # 是否启用增强功能（加密、压缩、数据库存储）\n    enabled: true\n    # 统一上传目录\n    upload-dir: upload\n    # 是否ZIP压缩（true=所有上传的文件都会压缩成zip格式）\n    zip-enabled: true\n    # 是否AES加密（true=所有上传的文件都会AES加密）\n    encrypt-enabled: false\n    # 是否保存到ImageFile数据库表（true=所有文件元数据存入ImageFile表）\n    save-to-db: true\n    # 图片尺寸压缩（仅对图片生效，减小图片分辨率/质量）\n    image-compress: true\n\n  auth:\n    #使用 @org.springblade.test.Sm2KeyGenerator 获取,用于国密sm2验签,需和前端保持一致\n    public-key: 04ac02fe94f4cac62a57a2335cc96a075a1ee41cea3b211bd7acbb9cf579b7e601b9ece2b0cfab64dca268b6942bf556af67cfe226a5cf28d936039c43e4bb12c1\n    #使用 @org.springblade.test.Sm2KeyGenerator 获取,用于国密sm2解密,前端无需配置\n    private-key: 00ac7fde22ecf5a764ea69b7ca8205383d98e7459e765bc1bd092f62c5f85267f9\n  token:\n    #使用 @org.springblade.test.SignKeyGenerator 获取\n    sign-key: qHJlcyzQ7YoGmHA7wZzvioTKYzYMaugG\n    #使用 @org.springblade.test.SignKeyGenerator 获取\n    aes-key: hJtodEd1qzJX9UOB9RBFdWk9KrAb59fH\n  xss:\n    enabled: true\n    skip-url:\n      - /weixin\n       # 富文本（TinyMCE）表单值/审批意见经 POST body 下发，不能被 XSS 过滤器清洗\n      # （XssHtmlFilter 白名单仅 a/b/em/i/img/strong，<p>/<br>/<table> 等会被剥掉）\n      # blade-formmode：表单数据 / 业务数据写入（Feign 直连，无 /api 前缀）\n      - /form-data/**\n      # blade-workflow：发起(意见+表单值) / 审批(意见+变量) / 测试提交\n      - /instance/**\n      - /task/**\n      - /test/**\n      # blade-workflow：表单保存与校验（body 含布局字段值与富文本）\n      - /form/**\n      # blade-workflow：BPMN XML 与节点/出口/权限配置（含 XML 标签，被清洗会破坏定义）\n      - /definition/**\n      # blade-workflow：自定义操作（意见文本）\n      - /custom-operation/**\n      # blade-workflow：子流程操作（说明文本）\n      - /subflow/**\n  secure:\n    skip-url:\n      - /test/**\n      - /blade-mall/front/**\n      - /blade-mall/uploads/**\n      - /blade-mall/file/download/**\n      - /blade-mall/auth/**\n      - /blade-mall/upload/**\n      - /file/download/**\n      - /front/**\n      - /uploads/**\n      - /auth/**\n    client:\n      - client-id: sword\n        path-patterns:\n          - /sword/**\n      - client-id: saber\n        path-patterns:\n          - /saber/**\n      - client-id: sword\n        path-patterns:\n          - /blade-mall/front/**\n  tenant:\n    column: tenant_id\n    tables:\n      - blade_notice\n\n# 微信小程序配置\nwechat:\n  miniapp:\n    appid: wx3d4a76c14ed1683b  # 请替换为实际的小程序AppID\n    secret: b1f771b0d92b9dcca5b260d91de53c22  # 请替换为实际的小程序AppSecret\n\n  # 微信支付配置\n  pay:\n    enabled: false  # 是否启用微信支付（true: 启用，false: 禁用）\n    appid: wx3d4a76c14ed1683b  # 小程序 AppID\n    mch-id: 1900000000  # 商户号，请替换为实际的商户号\n    mch-serial-no: b1f771b0d92b9dcca5b260d91de53c22  # 商户证书序列号\n    api-v3-key: your_api_v3_key_here  # APIv3 密钥（32 位）\n    private-key-path: src/main/resources/certs/apiclient_key.pem  # 商户私钥路径（需从微信商户平台下载）\n    platform-cert-path: src/main/resources/certs/wechatpay_cert.pem  # 微信支付平台证书路径\n    notify-url: https://your-domain.com/api/pay/wechat/notify  # 支付结果通知地址\n    refund-notify-url: https://your-domain.com/api/pay/wechat/refund/notify  # 退款通知地址\n\n# 第三方平台配置\nthird-party:\n  # 微信公众号/开放平台配置\n  wechat:\n    app-id: wxc771b90f4d13039e  # 请替换为实际的微信AppID\n    app-secret: 20be435da6771c5d86c4fd6eb097ad9b  # 请替换为实际的微信AppSecret\n    access-token-url: https://api.weixin.qq.com/sns/oauth2/access_token\n    user-info-url: https://api.weixin.qq.com/sns/userinfo\n  # 抖音配置\n  douyin:\n    client-key: your_douyin_client_key  # 请替换为实际的抖音Client Key\n    client-secret: your_douyin_client_secret  # 请替换为实际的抖音Client Secret\n    access-token-url: https://open.douyin.com/oauth/access_token/\n    user-info-url: https://open.douyin.com/oauth/userinfo/','5732d9dcdac37f4c292b57519a290594','2026-09-28 14:25:40','2026-09-28 06:25:40','nacos','192.168.1.5','U','1a1968dd-c688-4eae-8f3e-b41bb111b3b6','','formal','','{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"blade.yaml\"}'),(0,78,'blade-formmode-dev.yaml','DEFAULT_GROUP','','# blade-formmode dev 专属配置\nblade:\n  workflow:\n    trigger-from-flowable:\n      enabled: true','5411eb388b4533c89ceb8c3196ef0342','2026-10-02 14:31:46','2026-10-02 06:31:47','nacos','0:0:0:0:0:0:0:1','I','public','','formal','','{\"src_user\":\"nacos\",\"type\":\"yaml\"}'),(4,79,'blade-dev.yaml','DEFAULT_GROUP','','#spring配置\nspring:\n  data:\n    redis:\n      ##redis 单机环境配置\n      host: 127.0.0.1\n      port: 6379\n      password: 123456\n      database: 0\n      ssl:\n        enabled: false\n      ##redis 集群环境配置\n      #cluster:\n      #  nodes: 127.0.0.1:7001,127.0.0.1:7002,127.0.0.1:7003\n      #  commandTimeout: 5000\n\n#项目模块集中配置\nblade:\n  #通用开发生产环境数据库地址(特殊情况可在对应的子工程里配置覆盖)\n  datasource:\n    dev:\n      url: jdbc:mysql://127.0.0.1:3306/blade?useSSL=false&useUnicode=true&characterEncoding=utf-8&zeroDateTimeBehavior=convertToNull&transformedBitIsBoolean=true&tinyInt1isBit=false&allowMultiQueries=true&serverTimezone=GMT%2B8\n      username: root\n      password: 123456','775640df591beb0d87536bd4ff1199d2','2026-10-05 12:13:42','2026-10-05 04:13:42','nacos','192.168.1.5','U','public','','formal','','{\"type\":\"yaml\",\"src_user\":\"nacos\"}'),(4,80,'blade-dev.yaml','DEFAULT_GROUP','','{\"code\":0,\"message\":\"success\",\"data\":{\"id\":\"4\",\"namespaceId\":\"public\",\"groupName\":\"DEFAULT_GROUP\",\"dataId\":\"blade-dev.yaml\",\"md5\":\"775640df591beb0d87536bd4ff1199d2\",\"type\":\"yaml\",\"appName\":\"\",\"createTime\":1776697550000,\"modifyTime\":1776788636000,\"desc\":\"\",\"configTags\":null,\"content\":\"#spring配置\\nspring:\\n  data:\\n    redis:\\n      ##redis 单机环境配置\\n      host: 127.0.0.1\\n      port: 6379\\n      password: 123456\\n      database: 0\\n      ssl:\\n        enabled: false\\n      ##redis 集群环境配置\\n      #cluster:\\n      #  nodes: 127.0.0.1:7001,127.0.0.1:7002,127.0.0.1:7003\\n      #  commandTimeout: 5000\\n\\n#项目模块集中配置\\nblade:\\n  #通用开发生产环境数据库地址(特殊情况可在对应的子工程里配置覆盖)\\n  datasource:\\n    dev:\\n      url: jdbc:mysql://127.0.0.1:3306/blade?useSSL=false&useUnicode=true&characterEncoding=utf-8&zeroDateTimeBehavior=convertToNull&transformedBitIsBoolean=true&tinyInt1isBit=false&allowMultiQueries=true&serverTimezone=GMT%2B8\\n      username: root\\n      password: 123456\",\"encryptedDataKey\":\"\",\"createUser\":\"nacos\",\"createIp\":\"192.168.1.5\"}}\r\n  # P3-5 节点操作者改读 BPMN wf:operator 扩展（与 MI 注入配套：否则 MI 集合为空，节点会被引擎静默跳过）\r\n  workflow:\r\n    operator-from-bpmn:\r\n      enabled: true\r\n','4e189977f3b9bf65fc99ce7d8f2efbd7','2026-10-05 12:14:37','2026-10-05 04:14:37','nacos','192.168.1.5','U','public','','formal','','{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"open operator-from-bpmn switch\"}'),(4,81,'blade-dev.yaml','DEFAULT_GROUP','','#spring配置\nspring:\n  data:\n    redis:\n      ##redis 单机环境配置\n      host: 127.0.0.1\n      port: 6379\n      password: 123456\n      database: 0\n      ssl:\n        enabled: false\n      ##redis 集群环境配置\n      #cluster:\n      #  nodes: 127.0.0.1:7001,127.0.0.1:7002,127.0.0.1:7003\n      #  commandTimeout: 5000\n\n#项目模块集中配置\nblade:\n  #通用开发生产环境数据库地址(特殊情况可在对应的子工程里配置覆盖)\n  datasource:\n    dev:\n      url: jdbc:mysql://127.0.0.1:3306/blade?useSSL=false&useUnicode=true&characterEncoding=utf-8&zeroDateTimeBehavior=convertToNull&transformedBitIsBoolean=true&tinyInt1isBit=false&allowMultiQueries=true&serverTimezone=GMT%2B8\n      username: root\n      password: 123456\r\n  # P3-5 节点操作者改读 BPMN wf:operator 扩展（与 MI 注入配套：否则 MI 集合为空，节点会被引擎静默跳过）\r\n  workflow:\r\n    operator-from-bpmn:\r\n      enabled: true\r\n','7bf19467b0188302d8b7b1b0de0eca5c','2026-10-05 12:27:38','2026-10-05 04:27:39','nacos','192.168.1.5','U','public','','formal','','{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"open operator-from-bpmn switch\"}'),(2,82,'blade.yaml','DEFAULT_GROUP','','#服务器配置\nserver:\n  undertow:\n    # 以下的配置会影响buffer,这些buffer会用于服务器连接的IO操作,有点类似netty的池化内存管理\n    buffer-size: 1024\n    # 是否分配的直接内存\n    direct-buffers: true\n    # 线程配置\n    threads:\n      # 设置IO线程数, 它主要执行非阻塞的任务,它们会负责多个连接, 默认设置每个CPU核心一个线程\n      io: 16\n      # 阻塞任务线程池, 当执行类似servlet请求阻塞操作, undertow会从这个线程池中取得线程,它的值设置取决于系统的负载\n      worker: 400\n\n#spring配置\nspring:\n  cloud:\n    sentinel:\n      eager: true\n  gateway:\n    routes:\n      - id: blade-mall\n        uri: lb://blade-mall\n        predicates:\n          - Path=/blade-mall/**\n        filters:\n          - StripPrefix=1\n  devtools:\n    restart:\n      log-condition-evaluation-delta: false\n    livereload:\n      port: 23333\n\n#feign配置\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n\n#对外暴露端口\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \"*\"\n  endpoint:\n    health:\n      show-details: always\n\n#springdoc-openapi配置\nspringdoc:\n  default-flat-param-object: true\n\n#knife4j配置\nknife4j:\n  #启用\n  enable: true\n  #基础认证\n  basic:\n    enable: false\n    username: blade\n    password: blade\n  #增强配置\n  setting:\n    enableSwaggerModels: true\n    enableDocumentManage: true\n    enableHost: false\n    enableHostText: http://localhost\n    enableRequestCache: true\n    enableFilterMultipartApis: false\n    enableFilterMultipartApiMethodType: POST\n    language: zh_cn\n    enableFooter: false\n    enableFooterCustom: true\n    footerCustomContent: Copyright © 2026 SpringBlade All Rights Reserved\n\n#swagger配置信息\nswagger:\n  title: SpringBlade 接口文档系统\n  description: SpringBlade 接口文档系统\n  version: 4.8.0\n  license: Powered By SpringBlade\n  licenseUrl: https://bladex.cn\n  terms-of-service-url: https://bladex.cn\n  contact:\n    name: smallchill\n    email: bladejava@qq.com\n    url: https://gitee.com/smallc\n\n#blade配置\nblade:\n  datasource:\n    dev:\n      url: jdbc:mysql://localhost:3306/blade?useSSL=false&serverTimezone=Asia/Shanghai&characterEncoding=utf8mb4\n      username: root\n      password: 123456\n    order:\n      url: jdbc:mysql://localhost:3306/blade_order?useSSL=false&serverTimezone=Asia/Shanghai&characterEncoding=utf8mb4\n      username: root\n      password: 123456\n    pay:\n      url: jdbc:mysql://localhost:3306/blade_pay?useSSL=false&serverTimezone=Asia/Shanghai&characterEncoding=utf8mb4\n      username: root\n      password: 123456\n    workflow:\n      url: jdbc:mysql://localhost:3306/blade_workflow?useSSL=false&serverTimezone=Asia/Shanghai&characterEncoding=utf8mb4\n      username: root\n      password: 123456\n  upload-path: d:\\workproject\\springbladeandreact\\springBlade\\uploads\n\n  # =============================================\n  # 文件上传统一配置（所有服务共用）\n  # =============================================\n  file:\n    # 是否启用增强功能（加密、压缩、数据库存储）\n    enabled: true\n    # 统一上传目录\n    upload-dir: upload\n    # 是否ZIP压缩（true=所有上传的文件都会压缩成zip格式）\n    zip-enabled: true\n    # 是否AES加密（true=所有上传的文件都会AES加密）\n    encrypt-enabled: false\n    # 是否保存到ImageFile数据库表（true=所有文件元数据存入ImageFile表）\n    save-to-db: true\n    # 图片尺寸压缩（仅对图片生效，减小图片分辨率/质量）\n    image-compress: true\n\n  auth:\n    #使用 @org.springblade.test.Sm2KeyGenerator 获取,用于国密sm2验签,需和前端保持一致\n    public-key: 04ac02fe94f4cac62a57a2335cc96a075a1ee41cea3b211bd7acbb9cf579b7e601b9ece2b0cfab64dca268b6942bf556af67cfe226a5cf28d936039c43e4bb12c1\n    #使用 @org.springblade.test.Sm2KeyGenerator 获取,用于国密sm2解密,前端无需配置\n    private-key: 00ac7fde22ecf5a764ea69b7ca8205383d98e7459e765bc1bd092f62c5f85267f9\n  token:\n    #使用 @org.springblade.test.SignKeyGenerator 获取\n    sign-key: qHJlcyzQ7YoGmHA7wZzvioTKYzYMaugG\n    #使用 @org.springblade.test.SignKeyGenerator 获取\n    aes-key: hJtodEd1qzJX9UOB9RBFdWk9KrAb59fH\n  xss:\n    enabled: true\n    skip-url:\n      - /weixin\n      # 富文本（TinyMCE）表单值/审批意见经 POST body 下发，不能被 XSS 过滤器清洗\n      # （XssHtmlFilter 白名单仅 a/b/em/i/img/strong，<p>/<br>/<table> 等会被剥掉）\n      # blade-formmode：表单数据 / 业务数据写入（Feign 直连，无 /api 前缀）\n      - /form-data/**\n      # blade-workflow：发起(意见+表单值) / 审批(意见+变量) / 测试提交\n      - /instance/**\n      - /task/**\n      - /test/**\n      # blade-workflow：表单保存与校验（body 含布局字段值与富文本）\n      - /form/**\n      # blade-workflow：BPMN XML 与节点/出口/权限配置（含 XML 标签，被清洗会破坏定义）\n      - /definition/**\n      # blade-workflow：自定义操作（意见文本）\n      - /custom-operation/**\n      # blade-workflow：子流程操作（说明文本）\n      - /subflow/**\n  secure:\n    skip-url:\n      - /test/**\n      - /blade-mall/front/**\n      - /blade-mall/uploads/**\n      - /blade-mall/file/download/**\n      - /blade-mall/auth/**\n      - /blade-mall/upload/**\n      - /file/download/**\n      - /front/**\n      - /uploads/**\n      - /auth/**\n    client:\n      - client-id: sword\n        path-patterns:\n          - /sword/**\n      - client-id: saber\n        path-patterns:\n          - /saber/**\n      - client-id: sword\n        path-patterns:\n          - /blade-mall/front/**\n  tenant:\n    column: tenant_id\n    tables:\n      - blade_notice\n\n# 微信小程序配置\nwechat:\n  miniapp:\n    appid: wx3d4a76c14ed1683b  # 请替换为实际的小程序AppID\n    secret: b1f771b0d92b9dcca5b260d91de53c22  # 请替换为实际的小程序AppSecret\n\n  # 微信支付配置\n  pay:\n    enabled: false  # 是否启用微信支付（true: 启用，false: 禁用）\n    appid: wx3d4a76c14ed1683b  # 小程序 AppID\n    mch-id: 1900000000  # 商户号，请替换为实际的商户号\n    mch-serial-no: b1f771b0d92b9dcca5b260d91de53c22  # 商户证书序列号\n    api-v3-key: your_api_v3_key_here  # APIv3 密钥（32 位）\n    private-key-path: src/main/resources/certs/apiclient_key.pem  # 商户私钥路径（需从微信商户平台下载）\n    platform-cert-path: src/main/resources/certs/wechatpay_cert.pem  # 微信支付平台证书路径\n    notify-url: https://your-domain.com/api/pay/wechat/notify  # 支付结果通知地址\n    refund-notify-url: https://your-domain.com/api/pay/wechat/refund/notify  # 退款通知地址\n\n# 第三方平台配置\nthird-party:\n  # 微信公众号/开放平台配置\n  wechat:\n    app-id: wxc771b90f4d13039e  # 请替换为实际的微信AppID\n    app-secret: 20be435da6771c5d86c4fd6eb097ad9b  # 请替换为实际的微信AppSecret\n    access-token-url: https://api.weixin.qq.com/sns/oauth2/access_token\n    user-info-url: https://api.weixin.qq.com/sns/userinfo\n  # 抖音配置\n  douyin:\n    client-key: your_douyin_client_key  # 请替换为实际的抖音Client Key\n    client-secret: your_douyin_client_secret  # 请替换为实际的抖音Client Secret\n    access-token-url: https://open.douyin.com/oauth/access_token/\n    user-info-url: https://open.douyin.com/oauth/userinfo/','94059d53b1452f61e2775afc3ac223a7','2026-10-09 14:07:46','2026-10-09 06:07:47','nacos','0:0:0:0:0:0:0:1','U','public','','formal','','{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"blade.yaml\"}'),(9,83,'blade.yaml','DEFAULT_GROUP','','#服务器配置\nserver:\n  undertow:\n    # 以下的配置会影响buffer,这些buffer会用于服务器连接的IO操作,有点类似netty的池化内存管理\n    buffer-size: 1024\n    # 是否分配的直接内存\n    direct-buffers: true\n    # 线程配置\n    threads:\n      # 设置IO线程数, 它主要执行非阻塞的任务,它们会负责多个连接, 默认设置每个CPU核心一个线程\n      io: 16\n      # 阻塞任务线程池, 当执行类似servlet请求阻塞操作, undertow会从这个线程池中取得线程,它的值设置取决于系统的负载\n      worker: 400\n\n#spring配置\nspring:\n  cloud:\n    sentinel:\n      eager: true\n  gateway:\n    routes:\n      - id: blade-mall\n        uri: lb://blade-mall\n        predicates:\n          - Path=/blade-mall/**\n        filters:\n          - StripPrefix=1\n  devtools:\n    restart:\n      log-condition-evaluation-delta: false\n    livereload:\n      port: 23333\n\n#feign配置\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n\n#对外暴露端口\nmanagement:\n  endpoints:\n    web:\n    